<?php
declare(strict_types=1);
namespace OCA\BrTop\Permission;
use OCA\FlzPermissionMatrix\PublicApi\V1\{PermissionCondition,PermissionProvider,PermissionProviderDescriptor,PermissionProviderResult,PermissionRule};
final class BrTopPermissionProvider implements PermissionProvider{
 public function __construct(private BrTopPermissionSourceInterface $source){}
 public function descriptor():PermissionProviderDescriptor{return new PermissionProviderDescriptor('brtop','BRTop','1.0',['permissions']);}
 public function collect():PermissionProviderResult{$memberId=$this->source->memberGroupId();$chairId=$this->source->chairGroupId();$deputyId=$this->source->deputyGroupId();if($memberId===null||$chairId===null||$deputyId===null)return new PermissionProviderResult([],false,['Der kanonische LocalBase-BR-V1-Vertrag ist nicht gültig verfügbar; BRTop verweigert fachliche Rechte.']);$member=PermissionCondition::group($memberId);$chair=PermissionCondition::group($chairId);$admin=PermissionCondition::all([PermissionCondition::nextcloudAdmin(),PermissionCondition::temporaryAppAdminGrant()]);$rules=[
  $this->rule('Sitzungsprozess','Alle BR-Sitzungen','Sitzungen und zugehörige Inhalte lesen','brtop.session.read','Sitzungen lesen','all-sessions',$member),
  $this->rule('Sitzungsprozess','Alle BR-Sitzungen','Sitzungen, TOPs und Protokollinhalte bearbeiten','brtop.session.manage','Sitzungsprozess bearbeiten','all-sessions',$member),
  $this->rule('Dokument','Ladungen, Protokolle und Beschlüsse','Dokumente aus freigegebenen Fachdaten erzeugen und abrufen; Dateiinhalte werden vom Provider nicht untersucht','brtop.document.generate','Dokumente erzeugen','generated-documents',$member),
  $this->rule('Administration','BRTop-Konfiguration, Dokumentstammdaten, Vorlagen und Demo','Konfiguration und versionierte Vorlagen verwalten','brtop.settings.manage','Konfiguration verwalten','app-settings',$member,'brtop:BrAccessService'),
  $this->rule('Legislatur','Legislaturverwaltung','Anlegen und aktivieren','brtop.legislature.manage','Legislatur verwalten','legislature',$member),
  $this->rule('Abwesenheit','Bestätigte Abwesenheiten','Vorschläge prüfen und Bestätigungen speichern','brtop.absence.confirm','Abwesenheiten bestätigen','meeting-absence',$member),
  $this->rule('Administration','Zeitlich begrenzter Admin-Vollzugriff','Historie lesen sowie Freigaben für aktuelle native Administrationskonten erteilen oder widerrufen','brtop.admin_access.manage','Admin-Vollzugriff verwalten','all',$chair,'brtop:TemporaryAdminAccessService'),
  $this->rule('Administration','BR-Datenschutzberechtigung','Die persönliche BR-Datenschutzberechtigung ausschließlich aktuellen BR-Mitgliedern zuweisen oder entziehen','brtop.br_dpo.assign','BR-Datenschutzberechtigung verwalten','app-settings',$chair,'brtop:BrDpoAssignmentService'),
 ];foreach([['brtop.session.read','Sitzungen lesen','all-sessions'],['brtop.session.manage','Sitzungsprozess bearbeiten','all-sessions'],['brtop.document.generate','Dokumente erzeugen','generated-documents'],['brtop.settings.manage','Konfiguration verwalten','app-settings'],['brtop.legislature.manage','Legislatur verwalten','legislature'],['brtop.absence.confirm','Abwesenheiten bestätigen','meeting-absence']]as[$key,$label,$scope])$rules[]=$this->rule('Temporäre Administration',$label,'Nur native Nextcloud-Administration mit aktiver app-lokaler Freigabe',$key,$label,$scope,$admin,'brtop:BrAccessService');return new PermissionProviderResult($rules,false,['Persönliche app-lokale BR-Datenschutzzuweisungen sind im Matrix-V1-Bedingungsmodell nicht vollständig darstellbar; der BR-Vorsitz ist vollständig projiziert.']);}
 private function rule(string $type,string $name,string $detail,string $key,string $label,string $scope,PermissionCondition $condition,string $source='brtop:BrAccessMiddleware'):PermissionRule{return new PermissionRule($type,$name,$detail,$key,$label,'allow',$scope,$condition,$source,'high');}
}
